      for j in range(w):
        c=a[i][j]
        if c==bg or (i,j) in seen: continue
        q=[(i,j)]; seen.add((i,j)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for yy,xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
            if 0<=yy<h and 0<=xx<w and a[yy][xx]==c and (yy,xx) not in seen: seen.add((yy,xx)); q.append((yy,xx))
        ys=[y for y,x in comp]; xs=[x for y,x in comp]; t,b=min(ys),max(ys); l,r=min(xs),max(xs)
